package com.studentassignment.api;
import com.studentassignment.model.*; import java.time.*;
public final class Views {private Views(){} public record AssignmentView(Long id,String title,String description,String subject,Integer maxMarks,LocalDateTime deadline,Long createdBy,String createdByName,boolean hasInstructionFile,String instructionFileName,boolean isExpired){} public record SubmissionView(Long id,Long assignmentId,String assignmentTitle,String assignmentSubject,Long studentId,String studentName,String studentEmail,String fileName,LocalDateTime submittedAt,String status,Integer marks,Integer maxMarks,String feedback){} public record DashboardView(long totalSubmissions,long pendingReview,long graded,long late){}
 public static AssignmentView assignment(Assignment a){return new AssignmentView(a.getId(),a.getTitle(),a.getDescription(),a.getSubject(),a.getMaxMarks(),a.getDeadline(),a.getCreatedBy().getId(),a.getCreatedBy().getFullName(),a.getInstructionFilePath()!=null,a.getInstructionFileName(),a.getDeadline().isBefore(LocalDateTime.now()));}
 public static SubmissionView submission(Submission s){var a=s.getAssignment();var u=s.getStudent();return new SubmissionView(s.getId(),a.getId(),a.getTitle(),a.getSubject(),u.getId(),u.getFullName(),u.getEmail(),s.getFileName(),s.getSubmittedAt(),s.getStatus().name(),s.getMarks(),a.getMaxMarks(),s.getFeedback());}
}
